INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 4, 'theory', 'Quiz: shadow page tables, EPT/NPT, and huge pages');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 4, 0, 'What are shadow page tables for in the old scheme of memory virtualization?', '["They store memory snapshots for migration", "They translate the guest''s virtual address straight to the host one, and they are put into the real CR3", "They encrypt the guest''s memory", "They speed up disk I/O"]', 1, 'The hypervisor builds a shadow of the guest''s table and write-protects the original: an edit by the guest causes an exit, and the shadow gets updated.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 4, 1, 'What happens when the guest changes its page table with EPT/NPT enabled?', '["The guest exits so the hypervisor can update the shadow", "The guest asks the hypervisor to change CR3", "The guest changes it without a single exit: the nested tables belong to the hypervisor", "The guest blocks the other machines"]', 2, 'The guest keeps the first table, the hypervisor keeps the second, and the processor walks both. The guest''s edits are no longer intercepted.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 4, 2, 'How many memory accesses does a TLB miss take with a two-dimensional walk, when both the guest and the hypervisor have four levels of tables?', '["8", "16", "20", "24"]', 3, 'Five guest steps (four levels and the final address), five accesses each, minus one: 5 × 5 − 1 = 24. Without virtualization it is four.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 4, 3, 'How do huge pages help virtualization?', '["They shorten the table walk and let one TLB entry cover more memory", "They encrypt the guest''s memory", "They let KSM merge more pages", "They remove the need for nested tables"]', 0, 'A 2 MiB page removes one level of the walk, a 1 GiB page removes two. Incidentally, KSM doesn''t get along with big pages: they have to be split.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 4, 4, 'What happens on a nested page fault (EPT violation)?', '["The guest crashes", "The processor silently creates the mapping", "The guest''s tables are reset", "The guest exits to the hypervisor, which allocates a page, brings it in from swap, makes a copy on write, or emulates a device"]', 3, 'This is the basic mechanism behind lazy allocation, swapping, copy-on-write, and device emulation, and the following chapters are built on it.');
